// use_figma script. Generated by `python3 scripts/figma-script.py card …` — do not edit by hand.
// Writes ONLY on the QA page (its labels are in Italian, like the rest of that page).
// (Re)builds the QA card of each component in SET_IDS inside "QA / <library page of the component>":
// default + one instance per non-default value of every variant property (others at default)
// + one instance per inverted boolean. A value that exists only with other non-default values
// is shown with the closest existing variant and labelled "parziale"; a value that cannot be shown is "KO".
// Then pads cells whose instance overflows, and re-counts the summary (QA / Riepilogo).
/*__CONFIG__*/

const page = figma.root.children.find((p) => p.name === QA_PAGE);
if (!page) throw new Error(`No "${QA_PAGE}" page in this file: check figmaFileKey in config.json`);
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
await figma.loadFontAsync({ family: 'Inter', style: 'Bold' });
const GREY = { r: 0.42, g: 0.42, b: 0.47 },
  RED = { r: 0.82, g: 0.1, b: 0.1 },
  ORANGE = { r: 0.8, g: 0.45, b: 0 },
  GREEN = { r: 0.1, g: 0.55, b: 0.25 };
const txt = (s, size, bold, col) => {
  const t = figma.createText();
  t.fontName = { family: 'Inter', style: bold ? 'Bold' : 'Regular' };
  t.fontSize = size;
  t.characters = s;
  if (col) t.fills = [{ type: 'SOLID', color: col }];
  return t;
};
const AL = (dir, name, gap) => {
  const f = figma.createAutoLayout(dir, { name, itemSpacing: gap });
  f.fills = [];
  f.clipsContent = false;
  return f;
};
const root = page.findOne((n) => n.type === 'FRAME' && n.name === 'QA / Componenti');
const report = [];

for (const id of SET_IDS) {
  const comp = await figma.getNodeByIdAsync(id);
  if (!comp) {
    report.push({ id, error: 'not found' });
    continue;
  }
  let lp = comp;
  while (lp.type !== 'PAGE') lp = lp.parent;
  let sec = root.findChild((n) => n.name === 'QA / ' + lp.name);
  if (!sec) {
    // new library page: add a section
    sec = figma.createAutoLayout('VERTICAL', {
      name: 'QA / ' + lp.name,
      itemSpacing: 48,
      paddingLeft: 48,
      paddingRight: 48,
      paddingTop: 48,
      paddingBottom: 48,
    });
    sec.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    sec.cornerRadius = 16;
    sec.clipsContent = false;
    root.appendChild(sec);
    sec.appendChild(txt(lp.name, 48, true));
  }
  const old = sec.findChild((n) => n.getSharedPluginData('magma.qa', 'target') === id);
  const index = old ? sec.children.indexOf(old) : -1;
  const isSet = comp.type === 'COMPONENT_SET';
  const base = isSet ? comp.defaultVariant : comp;
  const defs = comp.componentPropertyDefinitions;
  const card = AL('VERTICAL', 'QA / ' + comp.name, 20);
  card.setSharedPluginData('magma.qa', 'target', id);
  if (index >= 0) {
    sec.insertChild(index, card);
    old.remove();
  } else sec.appendChild(card);
  card.appendChild(txt(comp.name, 24, true));
  card.appendChild(
    txt(
      `${id} · ${isSet ? comp.children.length + ' varianti' : 'componente singolo'}`,
      12,
      false,
      GREY,
    ),
  );
  const cur = isSet ? base.variantProperties : {};
  const cases = [{ group: 'default', label: 'default', props: {} }];
  for (const [k, d] of Object.entries(defs)) {
    if (d.type === 'VARIANT')
      for (const v of d.variantOptions)
        if (v !== cur[k])
          cases.push({ group: k, label: k + '=' + v, props: { [k]: v }, vk: k, vv: v });
    if (d.type === 'BOOLEAN') {
      const n = k.split('#')[0];
      cases.push({ group: n, label: n + '=' + !d.defaultValue, props: { [k]: !d.defaultValue } });
    }
  }
  const rows = {};
  const ko = [],
    partial = [];
  for (const c of cases) {
    if (!rows[c.group]) {
      const r = AL('HORIZONTAL', 'row / ' + c.group, 24);
      card.appendChild(r);
      const l = txt(c.group, 13, true);
      r.appendChild(l);
      l.resize(160, l.height);
      l.textAutoResize = 'HEIGHT';
      const w = AL('HORIZONTAL', 'cases', 24);
      r.appendChild(w);
      w.layoutWrap = 'WRAP';
      w.counterAxisSpacing = 24;
      w.resize(1600, 10);
      w.primaryAxisSizingMode = 'FIXED';
      w.counterAxisSizingMode = 'AUTO';
      rows[c.group] = w;
    }
    const cell = AL('VERTICAL', 'case / ' + c.label, 8);
    rows[c.group].appendChild(cell);
    let err = null,
      part = null,
      inst = base.createInstance();
    cell.appendChild(inst);
    try {
      if (Object.keys(c.props).length) inst.setProperties(c.props);
      if (c.vk) {
        const mc = await inst.getMainComponentAsync();
        if (mc.variantProperties[c.vk] !== c.vv) err = 'combinazione mancante';
      }
    } catch (e) {
      err = String(e.message || e).slice(0, 80);
    }
    if (err && c.vk) {
      // closest existing variant with that value
      let best = null,
        bd = 99;
      for (const v of comp.children) {
        if (v.variantProperties[c.vk] !== c.vv) continue;
        const d = Object.entries(v.variantProperties).filter(
          ([a, b]) => a !== c.vk && b !== cur[a],
        );
        if (d.length < bd) {
          bd = d.length;
          best = [v, d];
        }
      }
      if (best) {
        inst.remove();
        inst = best[0].createInstance();
        cell.insertChild(0, inst);
        part = 'solo con ' + best[1].map(([a, b]) => a + '=' + b).join(', ');
        err = null;
      }
    }
    cell.appendChild(
      txt(
        err ? c.label + ' — KO: ' + err : part ? c.label + ' — parziale: ' + part : c.label,
        11,
        false,
        err ? RED : part ? ORANGE : GREY,
      ),
    );
    if (err) ko.push(c.label + ': ' + err);
    if (part) partial.push(c.label + ': ' + part);
    // room for what renders outside the instance (open menus, focus rings, overflowing text)
    const rb = inst.absoluteRenderBounds,
      cb = cell.absoluteBoundingBox;
    if (rb) {
      const L = Math.max(0, cb.x - rb.x),
        R = Math.max(0, rb.x + rb.width - (cb.x + cb.width)),
        T = Math.max(0, cb.y - rb.y),
        B = Math.max(0, rb.y + rb.height - (cb.y + cb.height));
      if (L + R + T + B > 16) {
        cell.paddingLeft = Math.ceil(L) + 8;
        cell.paddingRight = Math.ceil(R) + 8;
        cell.paddingTop = Math.ceil(T) + 8;
        cell.paddingBottom = Math.ceil(B) + 8;
      }
    }
  }
  report.push({
    name: comp.name,
    section: sec.name,
    cases: cases.length,
    ko,
    partial,
    card: card.id,
  });
}

// summary re-count
const cells = page.findAll((n) => n.type === 'FRAME' && n.name.startsWith('case / '));
const labs = cells.map(
  (c) => (c.children.find((t) => t.type === 'TEXT') || { characters: '' }).characters,
);
const nKo = labs.filter((l) => l.includes(' KO')).length,
  nPart = labs.filter((l) => l.includes('parziale')).length;
const nCards = page.findAll(
  (n) => n.type === 'FRAME' && n.getSharedPluginData('magma.qa', 'target'),
).length;
const sum = page.findOne((n) => n.name === 'QA / Riepilogo');
if (sum)
  for (const t of sum.findAll((n) => n.type === 'TEXT')) {
    if (t.characters.startsWith('Copertura'))
      t.characters = t.characters
        .replace(/\d+ componenti/, nCards + ' componenti')
        .replace(/· \d+ casi/, `· ${cells.length} casi`);
    if (t.characters.startsWith('OK ·'))
      t.characters = `OK · ${cells.length - nPart - nKo} casi su ${cells.length}`;
    if (t.characters.startsWith('Parziali')) {
      const list = cells
        .filter((c, i) => labs[i].includes('parziale'))
        .map((c) => {
          let k = c;
          while (k && !k.getSharedPluginData('magma.qa', 'target')) k = k.parent;
          return (
            (k ? k.name.replace('QA / ', '') + ' ' : '') +
            c.children.find((x) => x.type === 'TEXT').characters.replace(' — parziale:', '')
          );
        });
      t.characters = `Parziali (${nPart}): ` + (list.join(' · ') || 'nessuno');
    }
    if (t.characters.startsWith('KO')) {
      t.characters = nKo ? `KO · ${nKo} casi: vedi le etichette rosse` : 'KO · nessuno';
      t.fills = [{ type: 'SOLID', color: nKo ? RED : GREEN }];
    }
  }
return { report, totals: { cards: nCards, cases: cells.length, partial: nPart, ko: nKo } };
